import 'package:audio_service/audio_service.dart';
import 'package:just_audio/just_audio.dart';\nimport '../models/song.dart';\n\nclass AudioServiceHandler extends BaseAudioHandler {\n  final AudioPlayer _player = AudioPlayer();\n  late Song _currentSong;\n\n  AudioServiceHandler() {\n    _setupAudioServiceListeners();\n  }\n\n  void _setupAudioServiceListeners() {\n    // Update media item when song changes\n    _player.sequenceStateStream.listen((state) {\n      if (state?.currentSource != null) {\n        // Update the UI with current playing info\n      }\n    });\n\n    // Update playback state\n    _player.playerStateStream.listen((playerState) {\n      _updatePlaybackState();\n    });\n\n    // Update position periodically\n    _player.positionStream.listen((_) {\n      _updatePlaybackState();\n    });\n  }\n\n  void _updatePlaybackState() {\n    final playing = _player.playing;\n    final position = _player.position;\n    final duration = _player.duration ?? Duration.zero;\n\n    playbackState.add(\n      playbackState.value.copyWith(\n        controls: [\n          MediaControl.skipToPrevious,\n          if (playing) MediaControl.pause else MediaControl.play,\n          MediaControl.skipToNext,\n        ],\n        systemActions: const {\n          MediaAction.seek,\n          MediaAction.seekForward,\n          MediaAction.seekBackward,\n        },\n        playing: playing,\n        processingState: const ProcessingState.ready(),\n        updatePosition: position,\n        bufferedPosition: duration,\n      ),\n    );\n  }\n\n  @override\n  Future<void> play() async {\n    await _player.play();\n    _updatePlaybackState();\n  }\n\n  @override\n  Future<void> pause() async {\n    await _player.pause();\n    _updatePlaybackState();\n  }\n\n  @override\n  Future<void> stop() async {\n    await _player.stop();\n    _updatePlaybackState();\n  }\n\n  @override\n  Future<void> skipToNext() async {\n    // Handled by music provider\n  }\n\n  @override\n  Future<void> skipToPrevious() async {\n    // Handled by music provider\n  }\n\n  @override\n  Future<void> seek(Duration position) async {\n    await _player.seek(position);\n    _updatePlaybackState();\n  }\n\n  @override\n  Future<void> setSpeed(double speed) async {\n    await _player.setSpeed(speed);\n    _updatePlaybackState();\n  }\n\n  void setSong(Song song, String title, String artist) {\n    _currentSong = song;\n    mediaItem.add(\n      MediaItem(\n        id: song.id,\n        album: song.album,\n        title: title,\n        artist: artist,\n        duration: song.duration,\n        artUri: song.albumArt != null ? Uri.parse(song.albumArt!) : null,\n      ),\n    );\n  }\n\n  AudioPlayer get audioPlayer => _player;\n}\n